import re,os,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
inp,out=G['Demo pair 1 input'],G['Demo pair 1 output']
H,W=len(inp),len(inp[0])
# find full-uniform lines in input
for r in range(H):
    if len(set(inp[r]))==1: print('full row',r,inp[r][0])
for c in range(W):
    col=[inp[r][c] for r in range(H)]
    if len(set(col))==1: print('full col',c,col[0])
# diff
diff=[(r,c,inp[r][c],out[r][c]) for r in range(H) for c in range(W) if inp[r][c]!=out[r][c]]
rows_d={r for r,_,_,_ in diff}; cols_d={c for _,c,_,_ in diff}
print('diff rows',sorted(rows_d),'cols',sorted(cols_d))
print('all diffs on those lines:', all(r in rows_d or c in cols_d for r,c,_,_ in diff))
print('nonuniform cells on lines all->2:', set(v for r,c,a,b in diff for v in [b]))
